    const start=state.files.findIndex(f=>f.path===state.anchorPath),end=state.files.findIndex(f=>f.path===path);
    if(start>=0&&end>=0)state.selectedPaths=state.files.slice(Math.min(start,end),Math.max(start,end)+1).map(f=>f.path);
