function extIconName(ext){return ['.jpg','.jpeg','.png','.gif','.bmp','.webp','.tif','.tiff'].includes(ext)?'image':ext==='.pdf'?'pdf':['.csv','.xlsx','.xls','.ods'].includes(ext)?'sheet':'file'}
