  backdrop.hidden=false;
  async function finishIntro(){
    state.hasSeenIntro=true;
    try{await window.pywebview.api.set_preference('has_seen_intro','1')}catch(e){}
    modalClose();
  }
  function updateSlide(newStep){
    currentStep=Math.max(0,Math.min(totalSteps-1,newStep));
    const carousel=$('#intro-carousel');
    if(carousel)carousel.innerHTML=renderSlide(currentStep);
    $$('.intro-dot').forEach((dot,idx)=>dot.classList.toggle('active',idx===currentStep));
    const prevBtn=$('#intro-prev');if(prevBtn)prevBtn.disabled=currentStep===0;
    const nextBtn=$('#intro-next');if(nextBtn)nextBtn.textContent=currentStep===totalSteps-1?tr('getStarted'):tr('next');
  }
  $('#intro-close').onclick=finishIntro;
  $('#intro-skip').onclick=finishIntro;
  $('#intro-prev').onclick=()=>updateSlide(currentStep-1);
  $('#intro-next').onclick=()=>{if(currentStep>=totalSteps-1)finishIntro();else updateSlide(currentStep+1)};
  $$('.intro-dot').forEach(btn=>btn.onclick=()=>updateSlide(Number(btn.dataset.step)));
