function bulkAction(action){
  if(action==='compare'){
    if(state.selectedPaths.length===2)compareDialog(state.selectedPaths[0],state.selectedPaths[1]);
    return;
  }
  if(action==='delete'){
    const body=`<div class="modal-body"><div class="settings-card"><div class="settings-card-copy"><div class="settings-card-title">${state.selectedPaths.length} ${esc(tr('selected'))}</div><div class="settings-card-desc">${esc(tr('confirmDeleteHint'))}</div></div></div></div>`;
    const foot=`<button class="modal-action" id="cancel-modal">${esc(tr('cancel'))}</button><button class="modal-action" id="bulk-confirm" style="color:#e19a93">${esc(tr('deleteFile'))}</button>`;
    modalOpen(tr('confirmDelete'),'',body,foot);$('#cancel-modal').onclick=modalClose;$('#bulk-confirm').onclick=()=>{modalClose();applyBulkAction('delete')};return;
  }
  if(action==='rename'){
    const previewNames = state.selectedPaths.slice(0,5).map(p => {
      const name = p.split(/[\\/]/).pop();
      const ext = name.includes('.') ? name.substring(name.lastIndexOf('.')) : '';
      const base = name.substring(0, name.length - ext.length);
      return `${base}${ext}`;
    });
    const body=`<div class="modal-body"><label class="field-label" for="bulk-prefix">${esc(tr('name'))}</label><input class="text-field" id="bulk-prefix" maxlength="40" placeholder="${esc(tr('renamePrefixExample'))}"/><div class="field-help">${state.language==='tr'?'Her dosya bu önek ve mevcut adıyla yeniden adlandırılır.':'Each file keeps its current name after this prefix.'}</div><div class="field-help" style="margin-top:8px;font-size:8px;color:var(--quiet)">${state.language==='tr'?'Örnek: ':'Example: '}${previewNames.map(n=>`<code>${esc(n)}</code>`).join(', ')}${state.selectedPaths.length>5?'…':''}</div></div>`;
    const foot=`<button class="modal-action" id="cancel-modal">${esc(tr('cancel'))}</button><button class="modal-action primary" id="bulk-confirm">${esc(tr('save'))}</button>`;
    modalOpen(tr('rename'),`${state.selectedPaths.length} ${tr('selected')}`,body,foot);$('#cancel-modal').onclick=modalClose;$('#bulk-confirm').onclick=()=>{const prefix=$('#bulk-prefix').value.trim();if(!prefix){toast(tr('name'),true);return}modalClose();applyBulkAction('rename',prefix)};return;
  }
  if(action==='tag'){
    const body=`<div class="modal-body"><label class="field-label" for="bulk-tags">${esc(tr('tags'))}</label><input class="text-field" id="bulk-tags" maxlength="400" placeholder="Work, Family, Travel"/><div class="field-help">${state.language==='tr'?'Bu etiketler seçili tüm dosyalara uygulanır. Virgülle ayır.':'These tags will be applied to all selected files. Separate with commas.'}</div></div>`;
    const foot=`<button class="modal-action" id="cancel-modal">${esc(tr('cancel'))}</button><button class="modal-action primary" id="bulk-confirm">${esc(tr('save'))}</button>`;
    modalOpen(tr('manageTags'),`${state.selectedPaths.length} ${tr('selected')}`,body,foot);$('#cancel-modal').onclick=modalClose;$('#bulk-confirm').onclick=()=>{const names=$('#bulk-tags').value.split(',').map(x=>x.trim()).filter(Boolean);modalClose();applyBulkAction('tag',names)};return;
  }
  if(action==='collection'){
    if(!state.collections.length){toast(tr('noCollections'),true);return}
    const body=`<div class="modal-body"><label class="field-label" for="bulk-collection">${esc(tr('allCollections'))}</label><select id="bulk-collection" class="text-field">${state.collections.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></div>`;
    const foot=`<button class="modal-action" id="cancel-modal">${esc(tr('cancel'))}</button><button class="modal-action primary" id="bulk-confirm">${esc(tr('addToCollection'))}</button>`;
    modalOpen(tr('addToCollection'),'',body,foot);$('#cancel-modal').onclick=modalClose;$('#bulk-confirm').onclick=()=>{const id=Number($('#bulk-collection').value);modalClose();applyBulkAction('collection',id)};return;
  }
  applyBulkAction(action);
}
async function healthDialog(){setStatus(state.language==='tr'?'Sağlık kontrolü çalışıyor…':'Checking library health…',true);const [d,activity]=await Promise.all([window.pywebview.api.get_diagnostics(),window.pywebview.api.get_activity_log(20)]);const h=d.health||{};const count=d.counts||{};const body=`<div class="modal-body health-body"><div class="health-grid"><div><b>${esc(state.language==='tr'?'Dosyalar':'Files')}</b><span>${count.files||0}</span></div><div><b>${esc(state.language==='tr'?'Eksik dosyalar':'Missing files')}</b><span>${h.missing_files||0}</span></div><div><b>${esc(state.language==='tr'?'Erişilemeyen kökler':'Unavailable folders')}</b><span>${h.missing_roots||0}</span></div><div><b>${esc(state.language==='tr'?'Eski indeks kayıtları':'Stale index rows')}</b><span>${h.stale_index_rows||0}</span></div><div><b>${esc(state.language==='tr'?'Boş disk alanı':'Free disk space')}</b><span>${h.free_bytes==null?'—':formatSize(h.free_bytes)}</span></div><div><b>${esc(state.language==='tr'?'Veritabanı':'Database')}</b><span>${esc(d.database?.integrity||'—')}</span></div><div><b>${esc(state.language==='tr'?'Klasör izleyicileri':'Folder watchers')}</b><span>${d.watchers?.active||0}</span></div><div><b>${esc(state.language==='tr'?'Çalışan işler':'Active jobs')}</b><span>${h.active_jobs||0}${h.scan_running?(state.language==='tr'?' · tarama':' · scan'):''}</span></div><div><b>${esc(state.language==='tr'?'Son yedek':'Last backup')}</b><span>${h.last_backup_time?formatDate(h.last_backup_time):'—'}</span></div></div><h4>${esc(tr('activity'))}</h4><div class="activity-list">${activity.length?activity.map(a=>`<div class="activity-row"><span>${esc(a.action)}</span><span>${a.item_count} · ${new Intl.DateTimeFormat(state.language==='tr'?'tr-TR':'en-US',{dateStyle:'short',timeStyle:'short'}).format(new Date(a.created*1000))}</span></div>`).join(''):`<div class="settings-empty">${esc(state.language==='tr'?'Henüz kayıtlı işlem yok.':'No recent activity.')}</div>`}</div></div>`;const foot=`<button class="modal-action" id="health-close">${esc(tr('close'))}</button>`;modalOpen(tr('health'),'',body,foot,true);$('#health-close').onclick=modalClose;setStatus(tr('readyOnDevice'))}
function settingsDialog(){state.settingsTab='general';renderSettings()}
