  const undoSave=$('#save-undo-options');if(undoSave)undoSave.onclick=async()=>{const r=await window.pywebview.api.save_undo_options({limit:Number($('#undo-limit').value),days:Number($('#undo-days').value)});if(!r.ok){toast(r.error,true);return}state.undoOptions=r.options;toast(state.language==='tr'?'Geri alma ayarları kaydedildi':'Undo retention saved')};
  const addFolder=$('#settings-add-folder');if(addFolder)addFolder.onclick=()=>{modalClose();addFolders()};
